def forward(self, x, t, c):
    h = self.inp(torch.cat([x, sinusoidal(t)], dim=1))
    gamma, beta = self.cond(c).chunk(2, dim=1)
    h = h * (1.0 + torch.tanh(gamma)) + beta
    return self.out(self.blocks(h))

