def forward(self, x, t, c):
    fr = c[:, 51:54]
    feats = []
    for f in (1.0, 2.0, 4.0, 8.0):
        feats.append(torch.sin(fr * f))
        feats.append(torch.cos(fr * f))
    c = torch.cat([c] + feats, dim=1)
    h = torch.cat([x, c, sinusoidal(t)], dim=1)
    return self.out(self.blocks(self.inp(h)))
